package com.hostel.hostelmanagement.service; import com.hostel.hostelmanagement.dto.*; import com.hostel.hostelmanagement.entity.User; import com.hostel.hostelmanagement.repository.UserRepository; import com.hostel.hostelmanagement.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; @Service public class AuthService {final UserRepository repo;final PasswordEncoder enc;final JwtService jwt;public AuthService(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;} public AuthResponse register(RegisterRequest r){if(repo.existsByEmail(r.getEmail()))throw new IllegalArgumentException("Email already registered");User u=new User(r.getName(),r.getEmail(),enc.encode(r.getPassword()),r.getRole());u.setPhone(r.getPhone());u.setDepartment(r.getDepartment());u.setStudentId(r.getStudentId());u=repo.save(u);return out(u);}public AuthResponse login(LoginRequest r){User u=repo.findByEmail(r.getEmail()).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!enc.matches(r.getPassword(),u.getPassword()))throw new IllegalArgumentException("Invalid email or password");return out(u);}AuthResponse out(User u){return new AuthResponse(jwt.generateToken(u.getEmail(),u.getRole().name()),u.getId(),u.getName(),u.getEmail(),u.getRole().name());}}